import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const d="/llamatron/assets/drift_editor.gEnUaziK.svg",p=JSON.parse('{"title":"Drift","description":"","frontmatter":{},"headers":[],"relativePath":"generators/DRIFT.md","filePath":"generators/DRIFT.md"}'),s={name:"generators/DRIFT.md"};function n(i,t,h,c,l,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="drift" tabindex="-1">Drift <a class="header-anchor" href="#drift" aria-label="Permalink to &quot;Drift&quot;">​</a></h1><p><img src="'+d+'" alt="A drift&#39;s settings, version A beside version B"></p><p>A drift slowly changes the clips that name it in their chains, over the whole song: their loudness, how often their notes play, the notes themselves, and their scale and root. A drift is one process for the whole song, so every clip that names the drift hears the same drift at the same moment, and the drift keeps changing through scenes where no clip hears it. A little drift keeps a gentle piece from sounding mechanical over its repeats; a lot makes a strange one wander.</p><p>A drift triggers every so often and picks new amounts, holding them until the next trigger. A drift has two versions of every setting, A and B, starts at A, and moves one step toward B at each trigger. A drift was built to be used mostly with its Restart at &quot;whole song&quot;, so that it runs from the top of the song through every scene.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>Enter</code> renames the drift, and every chain using it follows.</td></tr><tr><td>Every</td><td>How often it triggers: <code>1 bar</code> of the song, the default, or another time from the list every time setting shares.</td></tr><tr><td>Steps to B</td><td>How many triggers it takes to get from A to B, 16 unless set.</td></tr><tr><td>Direction</td><td><code>forward</code> goes from A to B and stays there, <code>loop</code> starts again at A, <code>pendulum</code> goes from A to B and back forever, and <code>brownian</code> wanders a step either way at each trigger.</td></tr><tr><td>Seed</td><td>The seed for its random choices. <code>Bksp</code> goes back to the song&#39;s seed.</td></tr><tr><td>Restart</td><td>When it starts over, as <a href="./../GENERATORS#restart">Generators</a> describes.</td></tr></tbody></table><h2 id="versions-a-and-b" tabindex="-1">Versions A and B <a class="header-anchor" href="#versions-a-and-b" aria-label="Permalink to &quot;Versions A and B&quot;">​</a></h2><p>Below the settings, each row has a value for A and for B side by side, the one Left and Right picked marked <code>&lt; &gt;</code>. <code>[</code> and <code>]</code> change the one picked, <code>Enter</code> types it or picks from a list, and <code>Bksp</code> clears it. Numbers are blended between A and B by how far the drift has moved, and a scale or a root is B&#39;s with a chance of how far it has moved.</p><table tabindex="0"><thead><tr><th>Row</th><th>What it does at each trigger</th></tr></thead><tbody><tr><td>AX+= to DX+=</td><td>Adds to the register, so that <code>+Note</code>, <code>+Vel</code>, the conditions and register binding all follow the drift.</td></tr><tr><td>Vel+=</td><td>Added to every note&#39;s velocity, kept between 1 and 127.</td></tr><tr><td>Prob ±</td><td>Added to every step&#39;s probability, from -100 to 100; a blank Probability counts as 100, so a negative amount brings in dropouts.</td></tr><tr><td>Degree +</td><td>Moves every note along the scale, from -7 to 7.</td></tr><tr><td>Degree random</td><td>Moves every note a random number of scale steps, up to this many either way, picked at each trigger and held until the next.</td></tr><tr><td>Scale, Scale prob</td><td>A scale of the song&#39;s that takes over the clips&#39; scale, with this chance at each trigger.</td></tr><tr><td>Root, Root prob</td><td>A root that takes over the scale&#39;s root, with this chance.</td></tr></tbody></table><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Add the drift to a chain, as <code>drift: name</code>, and give clips that chain. The drift&#39;s place in the chain doesn&#39;t matter, and an arpeggiator after the drift arpeggiates the drifted notes. <code>examples/by_genre/electronic/mainstreet_hoedown.yml</code> uses a very slight one on its loudness.</p>',11)])])}const m=e(s,[["render",n]]);export{p as __pageData,m as default};
